*/

/**
 * Report the files that are missing the Apache license header.
 *
 * Unlike `build/addHeader.js` this script never writes anything: it only
 * exits with a non-zero code so it can guard a commit. It is wired up as
 * the `checkheader` npm script and runs from `.husky/pre-commit`.
 *
 * Usage:
 *   node build/checkheader.js                 # check the whole repository
 *   node build/checkheader.js <file> [...]    # check the given files only
 */

const fs = require('fs');
const pathTool = require('path');
const chalk = require('chalk');
const preamble = require('./preamble');

// In the `.headerignore`, each line is a pattern in RegExp.
// All relative paths (based on the echarts base directory) are tested.
// The pattern should match the relative path completely.
const excludesPath = pathTool.join(__dirname, '../.headerignore');
const ecBasePath = pathTool.join(__dirname, '../');

function main() {
    const inputPaths = process.argv.slice(2).filter(function (arg) {
        return arg.charAt(0) !== '-';
    });

    const missing = [];
    const unknownType = [];

    eachFile(inputPaths, function (absolutePath, fileExt) {
        const fileStr = fs.readFileSync(absolutePath, 'utf-8');

        if (preamble.extractLicense(fileStr, fileExt)) {
            return;
        }

        // Consider binary files: only complain for files we know how to fix.
        (preamble.hasPreamble(fileExt) ? missing : unknownType)
            .push(pathTool.relative(ecBasePath, absolutePath));
    });

    if (unknownType.length) {
        console.log(chalk.yellow(
            '\nThe license header of these files can not be checked automatically:'
        ));
        unknownType.forEach(function (path) {
            console.log(chalk.yellow('  ' + path));
        });
        console.log(chalk.yellow(
            'Add them to `.headerignore` if they do not need a license header.'
        ));
    }

    if (!missing.length) {
        console.log(chalk.green('License header check passed.'));
        return;
    }

    console.log(chalk.red('\nMissing Apache license header in:'));
    missing.forEach(function (path) {
        console.log(chalk.red('  ' + path));
    });
    console.log(chalk.red(
        '\n' + missing.length + ' file(s) need a license header.'
        + '\nRun `npm run addheader` to insert it automatically,'
        + '\nor add the path to `.headerignore` when no header is required.'
    ));
    process.exit(1);
}

function eachFile(inputPaths, visit) {

    const excludePatterns = [];
    const extReg = /\.([a-zA-Z0-9_-]+)$/;

    prepareExcludePatterns();

    if (inputPaths.length) {
        inputPaths.forEach(function (inputPath) {
            travel(pathTool.relative(ecBasePath, pathTool.resolve(process.cwd(), inputPath)));
        });
    }
    else {
        travel('./');
    }

    function travel(relativePath) {
        if (isExclude(relativePath)) {
            return;
        }

        const absolutePath = pathTool.join(ecBasePath, relativePath);
        if (!fs.existsSync(absolutePath)) {
            return;
        }
        const stat = fs.statSync(absolutePath);

        if (stat.isFile()) {
            visit(absolutePath, getExt(absolutePath));
        }
        else if (stat.isDirectory()) {
            fs.readdirSync(absolutePath).forEach(function (file) {
                travel(pathTool.join(relativePath, file));
            });
        }
    }

    function prepareExcludePatterns() {
        const content = fs.readFileSync(excludesPath, {encoding: 'utf-8'});
        content.replace(/\r/g, '\n').split('\n').forEach(function (line) {
            line = line.trim();
            if (line && line.charAt(0) !== '#') {
                excludePatterns.push(new RegExp(line));
            }
        });
    }

    function isExclude(relativePath) {
        for (let i = 0; i < excludePatterns.length; i++) {
            if (excludePatterns[i].test(relativePath)) {
                return true;
            }
        }
    }

    function getExt(path) {
        if (path) {
            const matchResult = path.match(extReg);
            return matchResult && matchResult[1];
        }
    }
}

main();

